toad_implementation.code_blueprint:
canvas {
  size: 800px 650px;
  fill: #002B18;
  font-family: "Share Tech Mono, monospace";
}

>pcbGreen = #002B18;
>goldPad = #D4AF37;
>silkscreen = #FFFFFF;
>traceColor = #B58D2A;

rect #icPackage {
  at: center of canvas offset 0px -30px;
  size: 240px 240px;
  fill: #1A1A1A;
  stroke: >silkscreen;
  stroke-width: 2px;
  radius: 4px;
}

circle #pin1Index {
  at: top left of #icPackage offset 20px 20px;
  size: 14px;
  fill: >silkscreen;
}

text #icLabel {
  at: center of #icPackage;
  content: "STM32F401\nARM CORTEX-M4";
  font-size: 14px;
  font-weight: 700;
  color: >silkscreen;
}

circle #viaPad1 {
  at: left of #icPackage offset -80px -40px;
  size: 18px;
  fill: >goldPad;
}

rect #traceLine1 {
  at: right of #viaPad1;
  size: 80px 3px;
  fill: >traceColor;
}

text #pin1Name {
  at: left of #viaPad1 offset -60px 0px;
  content: "PA0 / ADC1";
  font-size: 11px;
  color: >silkscreen;
}

text #boardRevision {
  at: bottom right of canvas offset -40px -40px;
  content: "HW_REV_2.4 • ENIG RO-HS COMPLIANT";
  font-size: 11px;
  color: >silkscreen;
}
